import numpy as np


class FeasCouncilES:
    """
    Steady-state mixed-integer ES with Deb's feasibility rules and a multi-component feasibility council:
      * per-constraint log-violation ridge surrogates plus an objective surrogate fitted on feasible points;
      * violation-frequency weights cw_j so dominant constraints (e.g. constraint 2) dominate screening;
      * 12-mutant screening: exploit score = predicted objective + 3 * weighted predicted violation;
      * step-adaptive coordinate pattern probes around the incumbent (5-15% of evaluations);
      * feasibility bisection: an infeasible child is bisected toward the feasible incumbent (3 evals);
      * feasibility pull of predicted-infeasible children toward the incumbent;
      * 1/5-rule sigma for the GA part; restarts with log-uniform sigma reseeding after stalls;
      * binary SHAP-style bias from surrogate attributions biases binary flips.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        budget = self.budget
        dim = self.dim
        rng = np.random

        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        vt = list(func.variable_types)
        nv = np.ones(dim)
        for i in range(dim):
            if vt[i] != "continuous":
                nv[i] = float(func.n_values[i])
        cont = np.array([i for i in range(dim) if vt[i] == "continuous"], dtype=int)
        disc = np.array([i for i in range(dim) if vt[i] != "continuous"], dtype=int)
        is_bin = np.array([vt[i] == "binary" for i in range(dim)], dtype=bool)
        is_cont = np.array([vt[i] == "continuous" for i in range(dim)], dtype=bool)
        span = ub - lb
        dnorm = np.maximum(nv - 1.0, 1.0)
        ncon = int(func.n_constraints)

        S = {"evals": 0, "best_f": np.inf, "best_x": None, "attempts": 0}
        cache = {}
        archive = []
        vcount = np.zeros(ncon)
        cw = np.ones(ncon)
        models = {
            "ok": False,
            "wf": np.zeros(dim), "muf": np.zeros(dim),
            "wv": np.zeros((dim, ncon)), "muv": np.zeros(dim), "ymv": np.zeros(ncon),
        }
        bias = np.zeros(dim)
        pstep = np.full(dim, 0.05)
        state = {"last_fit": 0}
        PULL_THR = 0.02

        def repair(x):
            x = np.clip(x, lb, ub)
            if disc.size:
                x[disc] = np.clip(np.round(x[disc]), 0, nv[disc] - 1)
            return x

        def evaluate(x):
            x = repair(np.asarray(x, dtype=float))
            key = x.tobytes()
            if key in cache:
                return cache[key]
            f, g = func(x)
            S["evals"] += 1
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(), nan=1e6, posinf=1e6, neginf=0.0)
            g = np.maximum(g, 0.0)
            v = float(np.sum(g))
            f = float(f)
            if not np.isfinite(f):
                f = 1e30
                v = max(v, 1.0)
            entry = {"x": x.copy(), "f": f, "v": v, "g": g.copy()}
            cache[key] = entry
            archive.append(entry)
            vcount[:] += (g > 0).astype(float)
            cw[:] = 1.0 + 2.0 * vcount / max(1, len(archive))
            if v <= 0.0 and f < S["best_f"]:
                S["best_f"] = f
                S["best_x"] = x.copy()
            return entry

        def feat(x):
            z = np.asarray(x, dtype=float).copy()
            if disc.size:
                z[disc] = x[disc] / dnorm[disc]
            return z

        def ridge(X, Y, lam):
            mu = X.mean(axis=0)
            ym = Y.mean(axis=0)
            Xc = X - mu
            Yc = Y - ym
            W = np.linalg.solve(Xc.T @ Xc + lam * np.eye(X.shape[1]), Xc.T @ Yc)
            return W, mu, ym

        def refit():
            if len(archive) < 10:
                return
            Xa = np.array([feat(e["x"]) for e in archive])
            Ga = np.array([e["g"] for e in archive])
            Ya = np.log1p(np.minimum(Ga, 1e6))
            wv, muv, ymv = ridge(Xa, Ya, 1.0)
            upd = {"ok": True, "wv": wv, "muv": muv, "ymv": ymv}
            feas = [e for e in archive if e["v"] <= 0.0 and e["f"] < 1e29]
            if len(feas) >= 10:
                Xf = np.array([feat(e["x"]) for e in feas])
                yf = np.array([e["f"] for e in feas])
                fm, fs = yf.mean(), yf.std() + 1e-12
                wf, muf, _ = ridge(Xf, ((yf - fm) / fs)[:, None], 1.0)
                upd["wf"] = wf[:, 0]
                upd["muf"] = muf
            models.update(upd)
            if disc.size:
                wf = models["wf"]
                sf = wf[disc] / (np.std(wf[disc]) + 1e-12)
                wsum = models["wv"].sum(axis=1)
                sv = wsum[disc] / (np.std(wsum[disc]) + 1e-12)
                bias[disc] = 0.5 * np.tanh(sf) + 0.5 * np.tanh(sv)

        def predict(x):
            z = feat(x)
            pf = float((z - models["muf"]) @ models["wf"])
            lv = (z - models["muv"]) @ models["wv"] + models["ymv"]
            pvec = np.maximum(np.expm1(lv), 0.0)
            return pf, pvec

        def pen_of(pvec):
            return float(pvec @ cw)

        def rank(e):
            return (0, e["f"]) if e["v"] <= 0.0 else (1, e["v"])

        def random_point():
            x = np.empty(dim)
            if cont.size:
                x[cont] = rng.uniform(lb[cont], ub[cont])
            for i in disc:
                if is_bin[i]:
                    x[i] = 1.0 if rng.rand() < 0.3 else 0.0
                else:
                    x[i] = float(rng.randint(int(nv[i])))
            return repair(x)

        def tournament(pop):
            i, j = rng.randint(len(pop)), rng.randint(len(pop))
            a, b = pop[i], pop[j]
            return a if rank(a) <= rank(b) else b

        def mutate(x, sigma):
            c = x.copy()
            if cont.size:
                m = rng.rand(cont.size) < 0.5
                if not m.any():
                    m[rng.randint(cont.size)] = True
                idx = cont[m]
                if rng.rand() < 0.1:
                    step = np.clip(np.tan(np.pi * (rng.rand(idx.size) - 0.5)), -10, 10)
                else:
                    step = rng.randn(idx.size)
                c[idx] += sigma * span[idx] * step
            if disc.size:
                pd = min(0.8, max(0.1, 2.0 / disc.size))
                m = rng.rand(disc.size) < pd
                if not m.any():
                    m[rng.randint(disc.size)] = True
                for idx in disc[m]:
                    n = int(nv[idx])
                    if n <= 1:
                        continue
                    if vt[idx] == "categorical":
                        new = rng.randint(n - 1)
                        cur = int(round(c[idx]))
                        c[idx] = new if new < cur else new + 1
                    elif vt[idx] == "binary":
                        cur = int(round(c[idx]))
                        harmful = (cur == 1 and bias[idx] > 0.0) or (cur == 0 and bias[idx] < 0.0)
                        strength = min(1.0, abs(bias[idx]))
                        if harmful:
                            flip = rng.rand() < 0.6 + 0.4 * strength
                        else:
                            flip = rng.rand() < 0.3 * (1.0 - 0.5 * strength)
                        if flip:
                            c[idx] = 1.0 - cur
                    else:
                        if rng.rand() < 0.3:
                            c[idx] = rng.randint(n)
                        else:
                            c[idx] = c[idx] + (1.0 if rng.rand() < 0.5 else -1.0)
            return repair(c)

        def crossover(a, b):
            m = rng.rand(dim) < 0.5
            return np.where(m, a, b)

        def select_child(pop, sigma):
            K = 12
            cands = []
            for _ in range(K):
                p1 = tournament(pop)
                p2 = tournament(pop)
                base = crossover(p1["x"], p2["x"]) if rng.rand() < 0.5 else p1["x"]
                cands.append((mutate(base, sigma), p1))
            if not models["ok"]:
                return cands[0]
            preds = [predict(c) for c, _ in cands]
            pens = np.array([pen_of(pv) for _, pv in preds])
            pfs = np.array([pf for pf, _ in preds])
            if rng.rand() < 0.95:
                scores = pfs + 3.0 * pens
            else:
                scores = np.abs(pens - 0.01) + 0.1 * pfs
            k = int(np.argmin(scores))
            return cands[k]

        def pull(child, anchor):
            for t in (0.5, 0.25, 0.1):
                c = repair(anchor + t * (child - anchor))
                _, pvec = predict(c)
                if pvec.sum() < PULL_THR:
                    return c
            return child

        def pattern_child(x):
            i = rng.randint(dim)
            s = 1.0 if rng.rand() < 0.5 else -1.0
            c = x.copy()
            if is_cont[i]:
                c[i] += s * pstep[i] * span[i]
            else:
                c[i] += s
            return repair(c), i

        def insert(e, pop):
            worst_i = max(range(len(pop)), key=lambda k: rank(pop[k]))
            if rank(e) < rank(pop[worst_i]):
                pop[worst_i] = e

        def line_bisect(infeas_entry):
            # bisect between feasible incumbent (lo) and infeasible point (hi); returns feasible entries found
            lo = S["best_x"].copy()
            hi = infeas_entry["x"].copy()
            found = []
            for _ in range(3):
                if S["evals"] >= budget:
                    break
                mid = repair(0.5 * (lo + hi))
                me = evaluate(mid)
                found.append(me)
                if me["v"] <= 0.0:
                    lo = me["x"].copy()
                else:
                    hi = me["x"].copy()
            return found

        while S["evals"] < budget and S["attempts"] < 50 * budget:
            n0 = max(8, min(4 * dim + 4, budget - S["evals"]))
            if S["best_x"] is not None and rng.rand() < 0.5:
                sigma = float(np.exp(rng.uniform(np.log(1e-3), np.log(0.3))))
                anchor_restart = True
            else:
                sigma = 0.2
                anchor_restart = False
            pop = []
            if anchor_restart:
                pop.append(evaluate(mutate(S["best_x"], sigma)))
            while len(pop) < n0 and S["evals"] < budget:
                S["attempts"] += 1
                pop.append(evaluate(random_point()))
            if not pop or S["evals"] >= budget:
                break

            succ = 0
            trials = 0
            stall = 0
            last_best = S["best_f"]
            stall_limit = 30 * dim + 60

            while S["evals"] < budget and stall < stall_limit and S["attempts"] < 50 * budget:
                S["attempts"] += 1
                if S["evals"] - state["last_fit"] >= 15:
                    refit()
                    state["last_fit"] = S["evals"]

                u = rng.rand()
                kind = 2
                parent = None
                if u < 0.05:
                    child = random_point()
                    kind = 0
                elif u < 0.20 and S["best_x"] is not None:
                    child, parent = pattern_child(S["best_x"])
                    kind = 1
                else:
                    child, parent = select_child(pop, sigma)
                    if models["ok"] and S["best_x"] is not None:
                        _, pvec = predict(child)
                        if pvec.sum() >= PULL_THR:
                            child = pull(child, S["best_x"])

                before = S["best_f"]
                e = evaluate(child)

                if kind == 1:
                    success = (e["v"] <= 0.0) and (e["f"] < before)
                    pstep[parent] = float(np.clip(pstep[parent] * (1.5 if success else 0.8), 1e-4, 0.3))
                else:
                    insert(e, pop)
                    if kind == 2 and parent is not None and rank(e) < rank(parent):
                        succ += 1
                    trials += 1
                    if trials % 10 == 0:
                        rate = succ / 10.0
                        sigma = sigma * 1.3 if rate > 0.2 else sigma * 0.85
                        sigma = float(np.clip(sigma, 1e-4, 0.5))
                        succ = 0

                if e["v"] > 0.0 and S["best_x"] is not None and S["evals"] < budget - 3 and rng.rand() < 0.2:
                    for me in line_bisect(e):
                        insert(me, pop)

                if S["best_f"] < last_best - 1e-12:
                    last_best = S["best_f"]
                    stall = 0
                else:
                    stall += 1

            if S["evals"] >= budget:
                break

        return S["best_f"], S["best_x"]
